function $(e, t, n) {
	let r = `math.skill.${e.toLowerCase()}`;
	return {
		id: r,
		nameKey: `competency.${r}.name`,
		descriptionKey: `competency.${r}.description`,
		subjectId: "mathematics",
		targetGrade: 6,
		gradeCount: 5,
		frameworkSkillId: e,
		prerequisiteIds: t,
		scoreInputs: n.map((e) => ({
			kind: "activity",
			id: e
		}))
	};
}
